//! Rule 14 (`pca-action-schema` v1): the guest's `action_schema` module reproduces the TypeScript reference verdicts and
//! values recorded in `fixtures/ts_v2_schema.json` (generated by `gen_ts_v2_schema.ts`).
//! Every suite the guest implements (pq_suites: ed25519, ML-DSA-65/87, SLH-DSA-128f and hybrids) is held to exact TS parity;
//! verify cases marked `guest_unsupported` use a registered suite the guest lacks (less) and must fail with a reason
//! containing `unsupported_suite`.
use pca_zkvm_core::action_schema::{
    action_schema_digest, action_schema_shape_error, canon_projection, conform_action, reversibility_of, schema_verb,
    verb_reversibility, verify_action_schema,
};
use serde_json::Value;

fn fixture() -> Value {
    let p = concat!(env!("CARGO_MANIFEST_DIR"), "/../fixtures/ts_v2_schema.json");
    serde_json::from_str(&std::fs::read_to_string(p).expect("fixture")).expect("json")
}
fn s(v: &Value) -> Option<String> {
    v.as_str().map(String::from)
}
/// Reasons must match exactly, except the strict-canonical error text (`malformed schema: <TS throw message>`).
fn reason_eq(ts: &str, rs: &str) -> bool {
    if ts.starts_with("malformed schema:") {
        rs.starts_with("malformed schema:")
    } else {
        ts == rs
    }
}

#[test]
fn shape_matches_ts() {
    let f = fixture();
    let cases = f["shape"].as_array().unwrap();
    let mut bad = Vec::new();
    for c in cases {
        let got = action_schema_shape_error(&c["doc"], c["signed"].as_bool().unwrap());
        let want = s(&c["err"]);
        let same = match (&want, &got) {
            (None, None) => true,
            (Some(w), Some(g)) => reason_eq(w, g),
            _ => false,
        };
        if !same {
            bad.push(format!("{}: ts={want:?} rs={got:?}", c["name"]));
        }
    }
    assert!(bad.is_empty(), "shape cases differ:\n{}", bad.join("\n"));
    assert!(cases.len() > 150, "shape cases: {}", cases.len());
    eprintln!("shape: {} cases", cases.len());
}

/// The suite a verify case reaches the signature step with: `sig.alg` (absent = ed25519) when the key entry named by `sig.kid`
/// carries the same alg, and TS got that far (accepted, or failed exactly at the signature: "schema signature invalid").
/// The guest must then fail with `unsupported_suite` iff `pq_suites::suite_supported` says it lacks that suite.
fn guest_unsupported_suite(doc: &Value, keys: &Value, ts_ok: bool, ts_reason: Option<&str>) -> Option<String> {
    if !(ts_ok || ts_reason == Some("schema signature invalid")) {
        return None;
    }
    let alg_of = |v: Option<&Value>| match v {
        None => Some("ed25519".to_string()),
        Some(Value::String(a)) => Some(a.clone()),
        Some(_) => None,
    };
    let sig = doc.get("sig")?;
    let kid = sig.get("kid")?.as_str()?;
    let key = keys.as_array()?.iter().find(|k| k.is_object() && k.get("kid").and_then(Value::as_str) == Some(kid))?;
    let (sa, ka) = (alg_of(sig.get("alg"))?, alg_of(key.get("alg"))?);
    (sa == ka && !pca_zkvm_core::pq_suites::suite_supported(Some(&sa))).then_some(sa)
}

#[test]
fn verify_matches_ts() {
    let f = fixture();
    let cases = f["verify"].as_array().unwrap();
    let (mut bad, mut unsup) = (Vec::new(), 0);
    for c in cases {
        let got = verify_action_schema(&c["doc"], &c["keys"]);
        if guest_unsupported_suite(&c["doc"], &c["keys"], c["ok"].as_bool() == Some(true), c["reason"].as_str()).is_some() {
            unsup += 1;
            if !matches!(&got, Err(r) if r.contains("unsupported_suite")) {
                bad.push(format!("{}: must fail with unsupported_suite, got {got:?}", c["name"]));
            }
            continue;
        }
        let ok = c["ok"].as_bool().unwrap();
        let same = match &got {
            Ok(()) => ok,
            Err(r) => !ok && reason_eq(c["reason"].as_str().unwrap_or(""), r),
        };
        if !same {
            bad.push(format!("{}: ts ok={ok} reason={} rs={got:?}", c["name"], c["reason"]));
        }
    }
    assert!(bad.is_empty(), "verify cases differ:\n{}", bad.join("\n"));
    // PQ-signed schemas really verify (in TS and, by the parity above, in the guest)
    let pq_ok = cases.iter().filter(|c| c["name"].as_str().is_some_and(|n| n.starts_with("pq ")) && c["ok"].as_bool() == Some(true)).count();
    assert!(pq_ok >= 7, "PQ ok cases: {pq_ok}");
    assert!(unsup >= 2, "guest-unsupported cases (LESS): {unsup}");
    // the signed baseline verifies under the published key
    assert!(verify_action_schema(&f["signed"], &f["keys"]).is_ok());
    eprintln!("verify: {} cases ({} guest-unsupported, {} PQ accepted)", cases.len(), unsup, pq_ok);
}

#[test]
fn digest_matches_ts() {
    let f = fixture();
    let cases = f["digest"].as_array().unwrap();
    for c in cases {
        assert_eq!(action_schema_digest(&c["doc"]), s(&c["digest"]), "digest {}", c["name"]);
    }
    eprintln!("digest: {} cases", cases.len());
}

#[test]
fn conform_and_canon_match_ts() {
    let f = fixture();
    let cases = f["conform"].as_array().unwrap();
    let mut bad = Vec::new();
    let mut codes = std::collections::BTreeSet::new();
    for c in cases {
        let doc = if c["doc"].is_null() { &f["signed"] } else { &c["doc"] };
        let verb = c["verb"].as_str().unwrap();
        let got = conform_action(doc, verb, &c["params"]);
        let ok = c["ok"].as_bool().unwrap();
        match &got {
            Ok(()) => {
                if !ok {
                    bad.push(format!("{}: ts={} rs=ok", c["name"], c["code"]));
                    continue;
                }
                let canon = Value::Object(canon_projection(doc, verb, &c["params"]));
                if canon != c["canon"] {
                    bad.push(format!("{}: canon ts={} rs={canon}", c["name"], c["canon"]));
                }
                assert!(schema_verb(doc, verb).is_some());
            }
            Err(e) => {
                codes.insert(e.code.clone());
                if ok || Some(e.code.clone()) != s(&c["code"]) || e.path != s(&c["path"]) || Some(e.reason.clone()) != s(&c["reason"]) {
                    bad.push(format!("{}: ts=({}, {}, {}) rs={e:?}", c["name"], c["code"], c["path"], c["reason"]));
                }
            }
        }
    }
    assert!(bad.is_empty(), "conform cases differ:\n{}", bad.join("\n"));
    for code in ["params_not_object", "unknown_verb", "undeclared_param", "missing_param", "bad_type", "out_of_domain"] {
        assert!(codes.contains(code), "no case covers {code}");
    }
    eprintln!("conform: {} cases", cases.len());
}

#[test]
fn reversibility_matches_ts() {
    let f = fixture();
    let cases = f["rev"].as_array().unwrap();
    for c in cases {
        assert_eq!(reversibility_of(&c["verb"], &c["params"]), c["of"].as_str().unwrap(), "of {}", c["name"]);
        assert_eq!(verb_reversibility(&c["verb"]), c["max"].as_str().unwrap(), "max {}", c["name"]);
    }
    eprintln!("rev: {} cases", cases.len());
}

/// The conformance corpus (gen-conformance-intent-v2.mjs at HEAD, run in the fixture job): primitives.intent_schema
/// (sig / digest / conform) and the schema docs + keys of the schema-* vectors (requires_suite / reason_contains).
#[test]
fn conformance_corpus_matches() {
    let f = fixture();
    // Copied from packages/pca/conformance/vectors.json by the generator (absent only if that corpus has no intent_schema).
    let prims = match f["conformance_primitives"].as_array() {
        Some(p) => p,
        None => {
            panic!("fixture has no conformance primitives (vectors.json lacks primitives.intent_schema)");
        }
    };
    let mut bad = Vec::new();
    for c in prims {
        // `input_json` (README "Raw JSON text members"): the whole input as raw JSON text (keeps -0), used INSTEAD of `input`
        let raw: Option<Value> = c["input_json"].as_str().map(|t| serde_json::from_str(t).expect("input_json parses"));
        let (i, e, name) = (raw.as_ref().unwrap_or(&c["input"]), &c["expect"], &c["name"]);
        let _ = name;
        let sig = verify_action_schema(&i["schema"], &i["keys"]);
        let ts_sig = e["sig"].as_bool().unwrap();
        if guest_unsupported_suite(&i["schema"], &i["keys"], ts_sig, None).is_some() {
            if !matches!(&sig, Err(r) if r.contains("unsupported_suite")) {
                bad.push(format!("{name}: suite unsupported in the guest, must fail with unsupported_suite, got {sig:?}"));
            }
        } else if sig.is_ok() != ts_sig {
            bad.push(format!("{name}: sig ts={} rs={sig:?}", e["sig"]));
        }
        if e.get("digest").is_some() && action_schema_digest(&i["schema"]) != s(&e["digest"]) {
            bad.push(format!("{name}: digest"));
        }
        let got = conform_action(&i["schema"], i["verb"].as_str().unwrap_or(""), &i["params"]);
        let ce = &e["conform"];
        let same = match &got {
            Ok(()) => ce["ok"].as_bool() == Some(true),
            Err(x) => ce["ok"].as_bool() == Some(false) && Some(x.code.clone()) == s(&ce["code"]) && x.path == s(&ce["path"]),
        };
        if !same {
            bad.push(format!("{name}: conform ts={ce} rs={got:?}"));
        }
    }
    let vecs = f["conformance_vectors"].as_array().cloned().unwrap_or_default();
    for c in &vecs {
        let name = &c["name"];
        let got = verify_action_schema(&c["doc"], &c["keys"]);
        if let Some(rc) = c["reason_contains"].as_str() {
            if !matches!(&got, Err(r) if r.contains(rc)) {
                bad.push(format!("{name}: must fail with '{rc}', got {got:?}"));
            }
            continue;
        }
        if let Some(suite) = c["requires_suite"].as_str() {
            if !pca_zkvm_core::pq_suites::suite_supported(Some(suite)) {
                if !matches!(&got, Err(r) if r.contains("unsupported_suite")) {
                    bad.push(format!("{name}: {suite} unsupported in the guest, must fail with unsupported_suite, got {got:?}"));
                }
                continue;
            }
        }
        if got.is_ok() != c["ok"].as_bool().unwrap() {
            bad.push(format!("{name}: ts ok={} reason={} rs={got:?}", c["ok"], c["reason"]));
        }
    }
    assert!(bad.is_empty(), "conformance cases differ:\n{}", bad.join("\n"));
    assert!(!vecs.is_empty(), "no schema-* vectors");
    eprintln!("conformance: {} intent_schema primitives, {} schema-* vectors", prims.len(), vecs.len());
}
